    SELECT LAST_INSERT_ID()

/* setAlim */
INSERT INTO TB_ALIMXX (
            USER_NUMB
          , ALIM_NUMB
          , ALIM_SITU
          , TEMP_CODE
          , ALIM_TITL
          , ALIM_CONT
          , LINK_URLX
          , READ_YSNO
          , SEND_DATE
          , DELT_YSNO
)
SELECT #{userNumb}
     , LAST_INSERT_ID(COALESCE(MAX(ALIM.ALIM_NUMB), 0) + 1)
     , #{alimSitu}
     , #{tempCode}
     , #{alimTitl}
     , #{alimCont}
     , #{linkUrlx}
     , #{readYsno}
     , CURRENT_TIMESTAMP
     , #{deltYsno}
  FROM TB_ALIMXX ALIM
 WHERE ALIM.USER_NUMB = #{userNumb}

mapper.select:

SELECT /* dupSameAlimInHour */
       COUNT(*)
  FROM TB_ALIMXX
 WHERE USER_NUMB = #{userNumb}
   AND ALIM_SITU = #{alimSitu}
   AND TEMP_CODE = #{tempCode}
   AND COALESCE(ALIM_TITL, ' ') = COALESCE(#{alimTitl}, ' ')
   AND COALESCE(ALIM_CONT, ' ') = COALESCE(#{alimCont}, ' ')
   AND COALESCE(LINK_URLX, ' ') = COALESCE(#{linkUrlx}, ' ')
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}
   AND SEND_DATE >= CURRENT_TIMESTAMP - (1 / 24)

mapper.update:


UPDATE /* uptAlimRead */
       TB_ALIMXX
   SET READ_YSNO = #{commYes}
     , READ_DATE = CURRENT_TIMESTAMP
 WHERE USER_NUMB = #{userNumb}
   AND ALIM_NUMB = #{alimNumb}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}
   AND COALESCE(READ_YSNO, #{commNo}) = #{commNo}



UPDATE /* delAllAlim */
       TB_ALIMXX
   SET DELT_YSNO = #{commYes}
 WHERE USER_NUMB = #{userNumb}
   AND COALESCE(DELT_YSNO, #{commNo}) = #{commNo}

